  ('647a54ab-54de-402c-a36a-aaf0c36cffc3', 'ما اسم تقنية اندماج الرقصة الشهيرة بين محاربين لتكوين محارب جديد قوي؟', '["البوتارا","السينجوتسو","الفيوجن (Fusion Dance)","الكي"]'::jsonb, 2, 20, 17, 'multi', 'تنتج شخصيات مثل غوتينكس وغوجيتا.', 'medium', 'دراغون بول', ARRAY['أنمي', 'دراغون بول']::text[], 'Dragon Ball Z Lore', 'ANI-0062', true, 1),
